/**
 * Rebuilds src/presets.json, the bot's starting chain and token table, from the live Meson Explorer bundle.
 *
 * The running bot picks up new chains and tokens by itself (refreshPresets in src/meson.js), so this is not needed to keep it correct: it only updates the table the bot starts from, and the one the terminal tools use before their first refresh.
 * Reading the bundle lives in src/presets.js (fetchLiveChains), shared with the bot. It fails if any part cannot be read, so a failed run leaves the file as it was.
 */
// ----- Contents (generated by `npm run index` — do not edit) -----
// L15  Writing presets.json
// L20    main()
// ----- end of contents -----

import { writeFile } from 'node:fs/promises'
import { fetchLiveChains } from '../src/presets.js'

// =============================================================================
//   Writing presets.json
// =============================================================================

/** Read the live table and write src/presets.json. */
async function main () {
  const chains = await fetchLiveChains()
  const out = { generatedAt: new Date().toISOString(), source: 'https://explorer.meson.fi', chains }
  await writeFile(new URL('../src/presets.json', import.meta.url), JSON.stringify(out, null, 1) + '\n')
  console.log(`wrote src/presets.json — ${Object.keys(chains).length} chains`)
}

main().catch((err) => { console.error(err.message); process.exit(1) })
